    "supportDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\u042F\u043A\u0449\u043E \u0432\u0430\u043C \u043F\u043E\u0442\u0440\u0456\u0431\u043D\u0430 \u0434\u043E\u043F\u043E\u043C\u043E\u0433\u0430 \u0437 \u043F\u0456\u0434\u043A\u043B\u044E\u0447\u0435\u043D\u043D\u044F\u043C \u0434\u043E \u0432\u0430\u0448\u043E\u0433\u043E \u0437\u0430\u0441\u0442\u043E\u0441\u0443\u043D\u043A\u0443 Slack, \u0437\u0432\u0435\u0440\u043D\u0456\u0442\u044C\u0441\u044F \u0434\u043E \u043A\u0440\u043E\u043A\u0456\u0432 \u043D\u0438\u0436\u0447\u0435." } },
    "supportSetupHeading": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "1. \u041D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F \u0437\u0430\u0441\u0442\u043E\u0441\u0443\u043D\u043A\u0443" } },
    "supportSetupDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": '\u0417\u0430\u043B\u0435\u0436\u043D\u043E \u0432\u0456\u0434 \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u044C \u0432\u0430\u0448\u043E\u0433\u043E \u0440\u043E\u0431\u043E\u0447\u043E\u0433\u043E \u043F\u0440\u043E\u0441\u0442\u043E\u0440\u0443 Slack, \u0432\u0438 \u043C\u043E\u0436\u0435\u0442\u0435 \u0441\u0442\u0432\u043E\u0440\u0438\u0442\u0438 \u043D\u043E\u0432\u0438\u0439 \u0437\u0430\u0441\u0442\u043E\u0441\u0443\u043D\u043E\u043A Slack. \u0412 \u0456\u043D\u0448\u043E\u043C\u0443 \u0432\u0438\u043F\u0430\u0434\u043A\u0443 \u0430\u0434\u043C\u0456\u043D\u0456\u0441\u0442\u0440\u0430\u0442\u043E\u0440 \u043F\u043E\u0432\u0438\u043D\u0435\u043D \u0437\u0440\u043E\u0431\u0438\u0442\u0438 \u0446\u0435 \u0437\u0430 \u0432\u0430\u0441. \u042F\u043A\u0449\u043E \u0432\u0438 \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E \u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u043E\u0432\u0443\u0454\u0442\u0435 \u0456\u0441\u043D\u0443\u044E\u0447\u0438\u0439 \u0437\u0430\u0441\u0442\u043E\u0441\u0443\u043D\u043E\u043A, \u044F\u043A\u0438\u0439 \u043C\u043E\u0436\u0435 \u043D\u0430\u0434\u0441\u0438\u043B\u0430\u0442\u0438 \u043F\u043E\u0432\u0456\u0434\u043E\u043C\u043B\u0435\u043D\u043D\u044F, \u043F\u0435\u0440\u0435\u0439\u0434\u0456\u0442\u044C \u0434\u043E \u0440\u043E\u0437\u0434\u0456\u043B\u0443 "\u041F\u0456\u0434\u043A\u043B\u044E\u0447\u0435\u043D\u043D\u044F \u0434\u043E \u0432\u0430\u0448\u043E\u0433\u043E \u0437\u0430\u0441\u0442\u043E\u0441\u0443\u043D\u043A\u0443 Slack".' } },
    "supportSetupStep2": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": '\u0421\u0442\u0432\u043E\u0440\u0456\u0442\u044C \u043D\u043E\u0432\u0438\u0439 \u0437\u0430\u0441\u0442\u043E\u0441\u0443\u043D\u043E\u043A, \u0432\u0438\u0431\u0435\u0440\u0456\u0442\u044C "\u0417 \u043D\u0443\u043B\u044F" \u0442\u0430 \u0432\u0432\u0435\u0434\u0456\u0442\u044C \u043D\u0430\u0437\u0432\u0443. \u0412\u0438\u0431\u0435\u0440\u0456\u0442\u044C \u0440\u043E\u0431\u043E\u0447\u0438\u0439 \u043F\u0440\u043E\u0441\u0442\u0456\u0440, \u0443 \u044F\u043A\u043E\u043C\u0443 \u043F\u043E\u0432\u0438\u043D\u0435\u043D \u043F\u0440\u0430\u0446\u044E\u0432\u0430\u0442\u0438 \u0432\u0430\u0448 \u0437\u0430\u0441\u0442\u043E\u0441\u0443\u043D\u043E\u043A, \u0456 \u043D\u0430\u0442\u0438\u0441\u043D\u0456\u0442\u044C "\u0421\u0442\u0432\u043E\u0440\u0438\u0442\u0438".' } },
